        borderRadius: UI.RADIUS,
        fontSize: '13px',
        boxShadow: q.questId === expandedQuestId ? '0 0 18px rgba(140,164,188,0.16)' : 'none',
      });

      const header = document.createElement('button');
      header.type = 'button';
      Object.assign(header.style, {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
